console.log("js started"),window.onload=function(){console.log("window loaded");document.getElementById("vue-app")&&(window.hssVueTemplateApp=new Vue({el:"#vue-app",vuetify:new Vuetify,data:()=>({message:"Hello from Vue + Vuetify!",ajaxResponse:"",loading:!1,form:{field1:""},rules:{required:e=>!!e||"This field is required"}}),methods:{submitForm(){this.$refs.form.validate()&&(this.loading=!0,fetch(HSS_VUE_AJAX.ajax_url,{method:"POST",headers:{"Content-Type":"application/x-www-form-urlencoded"},body:new URLSearchParams({action:"hss_vue_sample_ajax",security:HSS_VUE_AJAX.nonce,type:"submit",field1:this.form.field1})}).then((e=>e.json())).then((e=>{this.ajaxResponse=e.success?e.data.message:e.data.message||"Something went wrong."})).catch((e=>{console.error("AJAX error:",e),this.ajaxResponse="Server error. Try again."})).finally((()=>{this.loading=!1})))}},mounted(){this.loading=!0,fetch(HSS_VUE_AJAX.ajax_url,{method:"POST",headers:{"Content-Type":"application/x-www-form-urlencoded"},body:new URLSearchParams({action:"hss_vue_sample_ajax",security:HSS_VUE_AJAX.nonce,type:"init"})}).then((e=>e.json())).then((e=>{console.log("AJAX response:",e)})).catch((e=>{console.error("AJAX error:",e)})).finally((()=>{this.loading=!1}))}}))};